import React, { useState, useRef } from 'react';
import ImageUploadCrop from './ImageUploadCrop';

function NewPropertyModal({
  propertyName, setPropertyName,
  propertyLocation, setPropertyLocation,
  propertyNeighborhood, setPropertyNeighborhood,
  propertyPrice, setPropertyPrice,
  propertyType, setPropertyType,
  propertyStatus, setPropertyStatus,
  propertyArea, setPropertyArea,
  propertyRooms, setPropertyRooms,
  propertyBathrooms, setPropertyBathrooms,
  propertyQuantity, setPropertyQuantity,
  propertyAvailability, setPropertyAvailability,
  propertyOwnerName, setPropertyOwnerName,
  propertyOwnerPhone, setPropertyOwnerPhone,
  propertyImageUrl, setPropertyImageUrl,
  propertyImages, setPropertyImages,
  handleAddProperty, handleUpdateProperty,
  editingProperty
}) {
  const [aiLoading, setAiLoading] = useState(false);
  const [showPreview, setShowPreview] = useState(false);
  const imageInputRef = useRef(null);

  const handleSubmit = (e) => {
    if (e) e.preventDefault();

    if (!propertyName || !propertyLocation || !propertyPrice || !propertyType || !propertyStatus || !propertyOwnerName || !propertyOwnerPhone) {
      alert('الرجاء تعبئة جميع الحقول الإلزامية:\n- وصف المذكرة/الكتاب\n- المحافظة\n- السعر\n- المادة\n- الترم/النوع\n- اسم المكتبة/الموزع\n- رقم الهاتف');
      return;
    }

    if (editingProperty) {
      handleUpdateProperty();
    } else {
      handleAddProperty();
    }
    document.querySelector('#newPropertyModal .btn-close')?.click();
  };

  const handleGenerateDescription = () => {
    setAiLoading(true);
    // Simulate AI call with smarter template
    setTimeout(() => {
      const type = propertyType || 'مذكرة';
      const status = propertyStatus || '';
      const city = propertyLocation || 'جميع المحافظات';
      const title = propertyNeighborhood || 'شرح وافي';

      let features = [];
      if (propertyArea) features.push(`إعداد مستر/ ${propertyArea}`);
      if (propertyRooms) features.push(`${propertyRooms} صفحة`);

      const specs = features.length > 0 
        ? `محتوى تعليمي متميز ${features.join('، ')}.` 
        : 'أقوى مذكرة شرح لهذا العام.';

      const priceText = propertyPrice ? `السعر: ${Number(propertyPrice).toLocaleString()} جنيه` : 'سعر رمزي';

      const desc = `🎓 لطلابنا الأعزاء! ${type} ${status} - ${title}\n\n` +
                   `📝 التفاصيل:\n` +
                   `${specs} طباعة كمبيوتر واضحة، تشمل شرح وتدريبات. ` +
                   `متاح الشحن لـ ${city}.\n\n` +
                   `⭐ المحتويات:\n` +
                   `- شرح مبسط للمنهج.\n` +
                   `- أسئلة النظام الجديد.\n` +
                   `- ${propertyAvailability === 'متاحة' ? 'متوفرة في المكتبة' : 'الكمية محدودة'}.\n\n` +
                   `💰 ${priceText}\n\n` +
                   `📞 للحجز والاستفسار:\n` +
                   `تواصل مع مكتبة${propertyOwnerName ? ' ' + propertyOwnerName : ''} على: ${propertyOwnerPhone || '...'}\n` +
                   `اطلب نسختك الآن قبل نفاذ الكمية!`;

      setPropertyName(desc);
      setAiLoading(false);
    }, 1000);
  };

  const handleImageUpload = async (e) => {
    if (e.target.files && e.target.files.length > 0) {
      const files = Array.from(e.target.files);
      for (const file of files) {
        const fd = new FormData();
        fd.append('file', file);
        try {
          const res = await fetch('/api/uploads', { method: 'POST', body: fd });
          if (!res.ok) throw new Error('Upload failed');
          const json = await res.json();
          setPropertyImages(prev => [...prev, json.url]);
        } catch (err) {
          setPropertyImages(prev => [...prev, URL.createObjectURL(file)]);
        }
      }
      if (imageInputRef.current) imageInputRef.current.value = '';
    }
  };

  const handleAddImage = () => {
    if (propertyImageUrl && !propertyImages.includes(propertyImageUrl)) {
      setPropertyImages([...propertyImages, propertyImageUrl]);
      setPropertyImageUrl('');
    }
  };

  const handleRemoveImage = (index) => {
    const newImages = propertyImages.filter((_, i) => i !== index);
    setPropertyImages(newImages);
  };

  const handleDragStart = (e, index) => {
    e.dataTransfer.setData('imageIndex', index);
  };

  const handleDrop = (e, dropIndex) => {
    const dragIndex = Number(e.dataTransfer.getData('imageIndex'));
    if (isNaN(dragIndex) || dragIndex === dropIndex) return;
    const newImages = [...propertyImages];
    const [draggedItem] = newImages.splice(dragIndex, 1);
    newImages.splice(dropIndex, 0, draggedItem);
    setPropertyImages(newImages);
  };

  const getDefaultImage = (type) => {
    switch (type) {
      case 'فيزياء': return 'https://images.unsplash.com/photo-1636466497217-26a8cbeaf0aa?auto=format&fit=crop&w=800&q=80';
      case 'كيمياء': return 'https://images.unsplash.com/photo-1532094349884-543bc11b234d?auto=format&fit=crop&w=800&q=80';
      case 'رياضيات': return 'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?auto=format&fit=crop&w=800&q=80';
      case 'أحياء': return 'https://images.unsplash.com/photo-1530026405186-ed1f139313f8?auto=format&fit=crop&w=800&q=80';
      default: return 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?auto=format&fit=crop&w=800&q=80';
    }
  };

  return (
    <div className="modal fade" id="newPropertyModal" tabIndex="-1" aria-labelledby="newPropertyModalLabel" aria-hidden="true">
      <div className="modal-dialog modal-lg">
        <div className="modal-content zoom-in">
          <div className="modal-header">
            <h5 className="modal-title" id="newPropertyModalLabel">
              {editingProperty ? 'تعديل الكتاب' : 'إضافة كتاب جديد'} {showPreview ? '- معاينة مباشرة' : ''}
            </h5>
            <button type="button" className="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
          </div>
          <div className="modal-body">
            {showPreview ? (
              <div className="card border-0 shadow-sm">
                <div className="position-relative">
                  <img 
                    src={(propertyImages.length > 0 ? propertyImages[0] : propertyImageUrl) || getDefaultImage(propertyType)} 
                    className="card-img-top rounded" 
                    alt="Preview" 
                    style={{height: '300px', objectFit: 'cover'}} 
                  />
                  <div className="position-absolute top-0 start-0 m-3">
                    <span className="badge bg-primary">{propertyType || 'المادة'}</span>
                    <span className="badge bg-secondary ms-1">{propertyStatus || 'الترم'}</span>
                  </div>
                  <div className="position-absolute bottom-0 end-0 m-3">
                    <span className="badge bg-dark fs-5">{Number(propertyPrice).toLocaleString()} ج</span>
                  </div>
                </div>
                <div className="card-body">
                  <h5 style={{ whiteSpace: 'pre-line' }}>{propertyNeighborhood || 'اسم المذكرة'}</h5>
                  <p className="text-muted">👨‍🏫 مستر/ {propertyArea || 'المدرس'} | 📍 {propertyLocation || 'المحافظة'}</p>
                  <hr/>
                  <div className="row text-center">
                    <div className="col"><strong>الصف:</strong> {propertyRooms}</div>
                    <div className="col"><strong>الصفحات:</strong> {propertyBathrooms}</div>
                    <div className="col"><strong>الكمية:</strong> {propertyQuantity}</div>
                  </div>
                  <hr/>
                  <div className="d-flex align-items-center">
                    <img src="https://cdn.pixabay.com/photo/2015/10/05/22/37/blank-profile-picture-973460_960_720.png" className="rounded-circle me-3 shadow-sm" style={{width: 50, height: 50, objectFit: 'cover'}} alt="Seller" />
                    <div>
                      <div className="fw-bold">{propertyOwnerName || 'اسم المكتبة'}</div>
                      <div className="small text-muted">📞 {propertyOwnerPhone || 'رقم الهاتف'}</div>
                    </div>
                  </div>
                </div>
              </div>
            ) : (
            <form onSubmit={handleSubmit}>
              <h6 className="mb-3 text-primary fw-bold">📝 تفاصيل الكتاب</h6>
              <div className="mb-3">
                <div className="d-flex justify-content-between align-items-center">
                  <label htmlFor="propertyName" className="form-label">وصف الكتاب</label>
                  <button type="button" className="btn btn-outline-primary btn-sm" onClick={handleGenerateDescription} disabled={aiLoading}>
                    {aiLoading ? '🧠 جاري التفكير...' : '✨ إنشاء بالذكاء الاصطناعي'}
                  </button>
                </div>
                <textarea className="form-control" id="propertyName" rows="5" value={propertyName} onChange={(e) => setPropertyName(e.target.value)} required placeholder="اكتب نبذة عن الكتاب وحالته..."></textarea>
              </div>

              <div className="row">
                <div className="col-md-6 mb-3">
                  <label htmlFor="propertyType" className="form-label">التصنيف</label>
                  <select className="form-select" id="propertyType" value={propertyType} onChange={(e) => setPropertyType(e.target.value)} required>
                    <option value="">اختر التصنيف</option>
                    <option value="رواية">رواية</option>
                    <option value="علوم">علوم</option>
                    <option value="تاريخ">تاريخ</option>
                    <option value="أطفال">أطفال</option>
                    <option value="تطوير ذات">تطوير ذات</option>
                    <option value="ديني">ديني</option>
                  </select>
                </div>
                <div className="col-md-6 mb-3">
                  <label htmlFor="propertyStatus" className="form-label">حالة الكتاب</label>
                  <select className="form-select" id="propertyStatus" value={propertyStatus} onChange={(e) => setPropertyStatus(e.target.value)} required>
                    <option value="">اختر الحالة</option>
                    <option value="جديد">جديد</option>
                    <option value="مستعمل">مستعمل</option>
                  </select>
                </div>
              </div>

              <hr className="my-4" />
              <h6 className="mb-3 text-primary fw-bold">📍 البيانات والموقع</h6>

              <div className="mb-3">
                <label htmlFor="propertyNeighborhood" className="form-label">اسم الكتاب</label>
                <input 
                  type="text" 
                  className="form-control" 
                  id="propertyNeighborhood" 
                  value={propertyNeighborhood || ''} 
                  onChange={(e) => setPropertyNeighborhood(e.target.value)} 
                  placeholder="اسم الكتاب..."
                />
              </div>

              <div className="mb-3">
                <label htmlFor="propertyLocation" className="form-label">مدينة البائع (للتسليم)</label>
                <input 
                  type="text" 
                  className="form-control" 
                  id="propertyLocation" 
                  value={propertyLocation || ''} 
                  onChange={(e) => setPropertyLocation(e.target.value)} 
                  placeholder="المدينة/المنطقة..."
                  required
                />
              </div>

              <div className="row">
                <div className="col-md-6 mb-3">
                  <label htmlFor="propertyPrice" className="form-label">السعر (ج)</label>
                  <input type="number" className="form-control" id="propertyPrice" value={propertyPrice} onChange={(e) => setPropertyPrice(e.target.value)} required />
                </div>
                <div className="col-md-6 mb-3">
                  <label htmlFor="propertyAvailability" className="form-label">التوفر</label>
                  <select className="form-select" id="propertyAvailability" value={propertyAvailability} onChange={(e) => setPropertyAvailability(e.target.value)}>
                    <option value="متاحة">متاحة</option>
                    <option value="غير متاحة">غير متاحة</option>
                    <option value="نفذت الكمية">نفذت الكمية</option>
                  </select>
                </div>
              </div>

              <div className="row">
                <div className="col-md-4 mb-3">
                  <label htmlFor="propertyArea" className="form-label">اسم المدرس</label>
                  <input type="text" className="form-control" id="propertyArea" value={propertyArea} onChange={(e) => setPropertyArea(e.target.value)} placeholder="مستر/..." />
                </div>
                <div className="col-md-4 mb-3">
                  <label htmlFor="propertyRooms" className="form-label">الصف الدراسي</label>
                  <input type="text" className="form-control" id="propertyRooms" value={propertyRooms} onChange={(e) => setPropertyRooms(e.target.value)} placeholder="مثال: 3 ثانوي" />
                </div>
                <div className="col-md-2 mb-3">
                  <label htmlFor="propertyBathrooms" className="form-label">عدد الصفحات</label>
                  <input type="number" className="form-control" id="propertyBathrooms" value={propertyBathrooms} onChange={(e) => setPropertyBathrooms(e.target.value)} placeholder="مثال: 150" />
                </div>
                <div className="col-md-2 mb-3">
                  <label htmlFor="propertyQuantity" className="form-label">الكمية</label>
                  <input type="number" className="form-control" id="propertyQuantity" value={propertyQuantity} onChange={(e) => setPropertyQuantity(e.target.value)} placeholder="50" />
                </div>
              </div>

              <hr className="my-4" />
              <h6 className="mb-3 text-primary fw-bold">👤 بيانات المكتبة/الموزع</h6>
              <div className="row">
                <div className="col-md-6 mb-3">
                  <label htmlFor="propertyOwnerName" className="form-label">اسم المكتبة / الموزع</label>
                  <input type="text" className="form-control" id="propertyOwnerName" value={propertyOwnerName} onChange={(e) => setPropertyOwnerName(e.target.value)} required />
                </div>
                <div className="col-md-6 mb-3">
                  <label htmlFor="propertyOwnerPhone" className="form-label">رقم الحجز (واتساب)</label>
                  <input type="text" className="form-control" id="propertyOwnerPhone" value={propertyOwnerPhone} onChange={(e) => setPropertyOwnerPhone(e.target.value)} required />
                </div>
              </div>

              <hr className="my-4" />
              <h6 className="mb-3 text-primary fw-bold">📷 الوسائط</h6>
              <div className="mb-3">
                <label htmlFor="propertyImageUrl" className="form-label">صورة الغلاف/المذكرة</label>
                <div className="input-group">
                  <input type="text" className="form-control" id="propertyImageUrl" placeholder="رابط الصورة" value={propertyImageUrl} onChange={(e) => setPropertyImageUrl(e.target.value)} />
                  <button type="button" className="btn btn-outline-primary" onClick={handleAddImage}>إضافة</button>
                  <button type="button" className="btn btn-outline-secondary" onClick={() => imageInputRef.current?.click()}>📂 رفع صور</button>
                  <button type="button" className="btn btn-outline-secondary" data-bs-toggle="modal" data-bs-target="#imageUploadCropModal">رفع و اقتصاص</button>
                </div>
                <input type="file" ref={imageInputRef} onChange={handleImageUpload} multiple accept="image/*" className="d-none" />
                <div className="d-flex flex-wrap mt-2 gap-2">
                  {propertyImages && propertyImages.map((img, index) => (
                    <div 
                      key={index} 
                      className="position-relative"
                      draggable
                      onDragStart={(e) => handleDragStart(e, index)}
                      onDragOver={(e) => e.preventDefault()}
                      onDrop={(e) => handleDrop(e, index)}
                      style={{ width: '80px', height: '80px', cursor: 'move' }}
                    >
                      <img src={img} alt={`img-${index}`} className="img-thumbnail w-100 h-100 object-fit-cover" />
                      <button 
                        type="button" 
                        className="btn btn-danger btn-sm position-absolute top-0 end-0 p-0" 
                        style={{ width: '20px', height: '20px', lineHeight: '1', fontSize: '12px' }}
                        onClick={() => handleRemoveImage(index)}
                      >&times;</button>
                    </div>
                  ))}
                </div>
              </div>
              <ImageUploadCrop showId="imageUploadCropModal" onUploaded={(url) => {
                setPropertyImages(prev => [...prev, url]);
                try { const m = window.bootstrap && window.bootstrap.Modal && window.bootstrap.Modal.getInstance(document.getElementById('imageUploadCropModal')); if (m) m.hide(); }
                catch (e) { /* ignore */ }
              }} />
            </form>
            )}
          </div>
          <div className="modal-footer">
            <button type="button" className="btn btn-outline-info me-auto" onClick={() => setShowPreview(!showPreview)}>
              {showPreview ? '✏️ العودة للتحرير' : '👁️ معاينة مباشرة'}
            </button>
            <button type="button" className="btn btn-secondary" data-bs-dismiss="modal">إلغاء</button>
            <button type="button" className="btn btn-primary" onClick={handleSubmit}>{editingProperty ? 'حفظ التعديلات' : 'نشر الكتاب'}</button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default NewPropertyModal;
